insert into public.reference_meta (id, version) values (true, '2026-10-29.4') on conflict (id) do update set version = excluded.version, updated_at = now();
insert into public.sources (id, title, publisher, url, source_type, published_on, accessed_on, notes) values
  ('src-pib-pmjay-6yrs', 'Transforming Healthcare: Six Years of Ayushman Bharat PM-JAY', 'Ministry of Health and Family Welfare (via PIB)', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2024/sep/doc2024923400001.pdf', 'official_primary', '2024-09-23', '2026-10-29', 'Coverage amount, cashless care, pre/post-hospitalisation days, SECC 2011 basis, portability.'),
  ('src-nha-70plus', 'Cabinet approves health coverage to all senior citizens of the age 70 years and above irrespective of income under AB PM-JAY (press release)', 'National Health Authority / PIB', 'https://nha.gov.in/img/resources/Press_Release.pdf', 'official_primary', '2024-09-11', '2026-10-29', 'Age 70+ eligibility irrespective of income, ₹5 lakh, top-up rules, CGHS/ECHS/CAPF choice, private insurance and ESI eligibility.'),
  ('src-ls-au2641', 'Lok Sabha Unstarred Question No. 2641 (cancer treatment under PM-JAY)', 'Ministry of Health and Family Welfare, answered in Lok Sabha', 'https://eparlib.nic.in/bitstream/123456789/2500970/1/AU2641.pdf', 'official_primary', '2023-08-04', '2026-10-29', '549 of 1,949 PM-JAY procedures are cancer-related; NHA MoU with National Cancer Grid and Tata Memorial Hospital; HMDG up to ₹1.25 lakh and RAN up to ₹15 lakh.'),
  ('src-nha-hbp21', 'Health Benefit Package 2.1 (AB PM-JAY package list)', 'National Health Authority', 'https://nha.gov.in/img/pmjay-files/HBP-2.1.pdf', 'official_primary', null, '2026-10-29', 'Package MC011 / procedure MC011A ''PTCA, inclusive of diagnostic angiogram'' (Cardiology). Rates are from HBP 2.1 and may since have been revised.'),
  ('src-nha-hbp20', 'Health Benefit Package 2.0 package master', 'National Health Authority', 'https://nha.gov.in/img/resources/HBP-2.0-Package-master.pdf', 'official_primary', null, '2026-10-29', 'Includes MO065B ''CT for Pediatric Acute Promyelocytic Leukemia Induction'' (Medical Oncology). Our checker could read only part of the file.'),
  ('src-manipur-grievance', 'PM-JAY grievance and helpline information', 'State Health Agency, Manipur (shamanipur.mn.gov.in)', 'https://shamanipur.mn.gov.in/Static/Grievance', 'official_secondary', null, '2026-10-29', 'Lists national helpline 14555 and the NHA grievance portal cgrms.nha.gov.in.'),
  ('src-aiimsbbsr-pmjay-doc', 'Updated information related to Ayushman Bharat', 'AIIMS Bhubaneswar', 'https://aiimsbhubaneswar.nic.in/wp-content/uploads/2026/05/UPDATED-INFORMATION-RELATED-TO-AYUSHMAN-BHARAT.pdf', 'hospital_official', null, '2026-10-29', 'Package-based cashless care; admission/discharge process with pre-authorisation and biometric verification; documents asked for at admission. Uploaded May 2026.'),
  ('src-aiimsbbsr-pmjay', 'Ayushman Bharat (PM-JAY) – patient process page', 'AIIMS Bhubaneswar', 'https://aiimsbhubaneswar.nic.in/schemes/ayushman-bharat-pm-jay/', 'hospital_official', null, '2026-10-29', 'Hospital''s own page describing its PM-JAY admission and discharge process at the Ayushman Bharat counter.'),
  ('src-aiimsbbsr-ran', 'Umbrella Scheme Rashtriya Arogya Nidhi (RAN)', 'AIIMS Bhubaneswar', 'https://aiimsbhubaneswar.nic.in/schemes/umbrella-scheme-rashtriya-arogya-nidhi-ran/', 'hospital_official', null, '2026-10-29', 'Eligibility routes, limits (RAN up to ₹15 lakh, HMDG up to ₹1.25 lakh), sanction process, documents, PM-JAY overlap.'),
  ('src-pib-ran-2022', 'Details of Financial Assistance for Poor Patients', 'Press Information Bureau (Lok Sabha written reply)', 'https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=1843846&reg=48&lang=2', 'official_primary', '2022-07-22', '2026-10-29', 'Umbrella RAN: one-time assistance up to ₹15 lakh (₹20 lakh rare diseases), released to treating government hospitals; HMDG up to ₹1.25 lakh for annual family income up to ₹1.25 lakh.'),
  ('src-ls-au5561', 'Lok Sabha Unstarred Question No. 5561 (Health Minister''s Cancer Patient Fund)', 'Ministry of Health and Family Welfare, answered in Lok Sabha', 'https://eparlib.sansad.in/bitstream/123456789/3010946/1/AU5561_tNqey7.pdf', 'official_primary', '2025-04-04', '2026-10-29', 'HMCPF: one-time assistance up to ₹15 lakh for cancer patients below the State/UT poverty line at RCCs, TCCCs, SCIs and other government hospitals.'),
  ('src-mohfw-ran', 'Rashtriya Arogya Nidhi', 'Ministry of Health and Family Welfare', 'https://mohfw.gov.in/major-programmes/poor-patients-financial-assistance/rashtriya-arogya-nidhi', 'official_primary', null, '2026-10-29', 'Names AIIMS New Delhi among central institutes holding a RAN revolving fund. Its ₹2 lakh per-case figure appears to predate the 2019 umbrella guidelines and is NOT used for amounts.'),
  ('src-iggmc-integrated', 'Integrated Ayushman Bharat – PMJAY and MJPJAY (scheme summary)', 'Indira Gandhi Government Medical College website (iggmc.edu.in)', 'https://iggmc.edu.in/wp-content/uploads/2026/04/Integrated-Ayushman-Bharat.pdf', 'official_secondary', null, '2026-10-29', '₹5 lakh floater, beneficiary categories A–E, 1,356 packages / 34 specialties, assurance mode, documents, GR dated 28 July 2023, expanded scope from 1 July 2024. Uploaded April 2026. The primary portal jeevandayee.gov.in could not be fetched.'),
  ('src-pmnrf', 'Prime Minister''s National Relief Fund – official website', 'Prime Minister''s Office', 'https://pmnrf.gov.in/', 'official_primary', null, '2026-10-29', 'Partial assistance for heart surgery, kidney transplantation, cancer treatment and acid-attack cases; government and empanelled private hospitals.'),
  ('src-gcri-pmnrf', 'PM Relief Fund information sheet', 'Gujarat Cancer & Research Institute (gcriindia.org)', 'https://www.gcriindia.org/Download/PM%20RELIEF%20FUND%20(English).pdf', 'hospital_official', null, '2026-10-29', 'PMNRF contact: Under Secretary (Funds), PMO, South Block, New Delhi-110011; phone 011-23013683.'),
  ('src-tmh-booklet', 'Tata Memorial Hospital patient booklet', 'Tata Memorial Centre (tmc.gov.in)', 'https://tmc.gov.in/event/upload/12112025_5/TMH_Brochure_%20patient%20booklet.pdf', 'hospital_official', null, '2026-10-29', 'Lists MJPJAY, AB-PMJAY, PMNRF and CMRF among schemes; scheme help at the Medical Social Services Department (Golden Jubilee Block, ground floor); adult haematology clinics for acute leukaemia and CML; board line 022 2417 7000.'),
  ('src-ls-au720', 'Lok Sabha Unstarred Question No. 720 (health insurance for senior citizens)', 'Ministry of Health and Family Welfare, answered in Lok Sabha', 'https://eparlib.sansad.in/bitstream/123456789/2983600/1/AU720_T12thL.pdf', 'official_primary', '2024-11-29', '2026-10-29', 'AB PM-JAY covers 1,961 procedures across 27 specialties including Orthopaedics; names Total Hip Replacement, Total Knee Replacement and PTCA among services available to eligible senior citizens; states may customise packages.'),
  ('src-punjab-sha-hbp20', 'HBP 2.0 packages reserved for government hospitals under AB-SSBY (20 Aug 2020 – 19 Aug 2021)', 'State Health Agency, Punjab', 'https://sha.punjab.gov.in/Security_audit/shapunjab/downloadfiles/letters/Order_reagrding_25_packages_HBP20.pdf', 'official_secondary', null, '2026-10-29', 'Historical (2020–21) Punjab list. Shows HBP 2.0 package SB039 ''Total Knee Replacement – Primary'' and ''– Revision''. Used only for the package code and as an example that states can reserve packages for public hospitals; not a current rule.'),
  ('src-sha-kerala-kasp', 'Karunya Arogya Suraksha Padhathi (KASP)', 'State Health Agency Kerala, Government of Kerala', 'https://sha.kerala.gov.in/?page_id=110&lang=en', 'official_primary', null, '2026-10-29', '₹5 lakh per family per year, family floater, cashless; ~42 lakh families in the bottom 40% (SECC 2011 criteria); no cap on family size or age; ~1,573 procedures; RSBY, CHIS, SCHIS and KBF merged in; state implements in trust mode since 1 Jul 2020; helpline 0471 4063121.'),
  ('src-sha-kerala-kbf', 'Karunya Benevolent Fund (KBF)', 'State Health Agency Kerala, Government of Kerala', 'https://sha.kerala.gov.in/?page_id=2961&lang=en', 'official_primary', null, '2026-10-29', 'Revamped KBF integrated with KASP/PM-JAY: cancer, haemophilia, kidney and heart disease, palliative care; annual family income below ₹3 lakh; KASP packages incl. 15 days post-discharge medicines; ration card with income proof; apply directly at a KASP-empanelled hospital, cashless. Old lottery-run limits: ₹2 lakh tertiary, ₹3 lakh kidney.'),
  ('src-dhn-kerala-uhc', 'Kerala Gov Clears Universal Health Coverage Plan to Bridge Insurance Gaps', 'Digital Health News (news report)', 'https://www.digitalhealthnews.com/kerala-gov-clears-universal-health-coverage-plan-to-bridge-insurance-gaps', 'news_report', '2026-08-13', '2026-10-29', 'Reports in-principle approval of a ''Health Protection for All'' programme for residents outside KASP/KBF/MEDISEP; no start date. Describes KBF as up to ₹2 lakh (plus ₹1 lakh for kidney disease) for families under ₹3 lakh income not in KASP.'),
  ('src-mjpjay-1356', '1356 – Package Master (Integrated MJPJAY / AB PM-JAY)', 'State Health Assurance Society, Maharashtra (jeevandayee.gov.in)', 'https://www.jeevandayee.gov.in/MJPJAY/RGJAYDocuments/1356%20-%20Package%20Master.pdf', 'official_primary', null, '2026-10-29', 'Read up to row 546 (our text extraction is capped; Orthopaedics comes later and was not reached). Cardiology M7: Coronary Balloon Angioplasty M7F1.1 ₹60,000; PTCA Additional Stent M7F1.2 ₹20,000. Haemato Oncology M19: AML induction/consolidation (M19U3.1/.2), ALL induction/consolidation/maintenance (M19U2.x), APML/ATO-ATRA regimens, BFM/MCP-841 protocols.'),
  ('src-mjpjay-hospitals', 'List of Empanelled hospital under Mahatma Jyotiba Phule Jan Arogya Yojana', 'State Health Assurance Society, Maharashtra (jeevandayee.gov.in)', 'https://www.jeevandayee.gov.in/RGJAYDocuments/Empanelled_Hospitals_Under_MJPJAY.pdf', 'official_primary', null, '2026-10-29', 'Undated list (about 490 hospitals, district / location / name / Pvt-Govt / single-multi). It does not list specialities, and empanelment changes over time.'),
  ('src-aiimsngp-joint', 'AIIMS Nagpur achieves landmark 550 joint replacements under the MJPJAY & PMJAY schemes', 'AIIMS Nagpur (aiimsnagpur.edu.in)', 'https://aiimsnagpur.edu.in/news/news/550-joint-replacement-surgeries-done-under-department-of-orthopedics%2C-aiims-nagpur', 'hospital_official', null, '2026-10-29', 'Undated hospital news: Department of Orthopaedics performed total knee, hip and shoulder replacements over three years under MJPJAY and PMJAY, free for economically weaker sections. Address and helpline from the institute''s CPIO page.'),
  ('src-sha-kerala-contract', 'AB PM-JAY–KASP: Schedules to Service Contract', 'State Health Agency Kerala / Department of Health & Family Welfare, Government of Kerala', 'https://sha.kerala.gov.in/wp-content/uploads/2020/12/Pub-EHCP-claims-Schedules-to-contract.pdf', 'official_primary', '2020-12-24', '2026-10-29', 'Schedule 3(a) names the HBP 2.0 package list as KASP''s package list (enclosed separately; not available to us). Historical (2020) — the current Kerala list may differ.')
insert into public.medical_needs (id, name, kind, specialty, summary, sort_order) values
  ('knee-replacement', 'Knee replacement', 'procedure', 'Orthopaedics', 'Surgery to replace a damaged knee joint. Some schemes have age-based routes, such as cover for people aged 70 and above.', 1),
  ('leukemia', 'Leukaemia', 'disease', 'Medical oncology / haematology', 'A blood cancer treated with chemotherapy, targeted medicines or transplant. Cancer-specific funds may apply.', 2),
  ('angioplasty', 'Angioplasty', 'procedure', 'Cardiology', 'A procedure to open a narrowed heart artery, usually with a stent.', 3)
insert into public.schemes (id, official_name, short_name, issuing_authority, scope, applicable_states, summary, intended_beneficiaries, benefit_amount_inr, benefit_unit, benefit_mechanism, payment_recipient, benefit_details, patient_costs_note, application_channel, application_steps, application_url, application_url_status, info_url, hospital_directory_url, helpdesk, verification_status, last_verified_on, source_updated_on, uncertainty_notes, is_demo) values
  ('pmjay-family', 'Ayushman Bharat – Pradhan Mantri Jan Arogya Yojana (AB PM-JAY)', 'PM-JAY', 'National Health Authority, Ministry of Health and Family Welfare, Government of India', 'national', '{}'::text[], 'Publicly funded health assurance: cashless secondary and tertiary hospitalisation for eligible families at empanelled public and private hospitals across India.', 'Families identified as eligible from the Socio-Economic Caste Census (SECC) 2011 data — described officially as the poorest 40% of the population — and groups added by later expansions.', 500000, 'per family per year, shared by all members (floater)', 'cashless_package', 'hospital', '[{"text":"Annual cover of up to ₹5 lakh per entitled family for secondary and tertiary hospitalisation.","source_id":"src-pib-pmjay-6yrs"},{"text":"Cashless treatment at the point of care in empanelled public and private hospitals.","source_id":"src-pib-pmjay-6yrs"},{"text":"Covers up to 3 days of pre-hospitalisation and up to 15 days of post-hospitalisation expenses, including diagnostics and medicines.","source_id":"src-pib-pmjay-6yrs"},{"text":"Assistance is package-based: the scheme pays the hospital a pre-defined rate for the approved package.","source_id":"src-aiimsbbsr-pmjay-doc"},{"text":"Reference rate for angioplasty in HBP 2.1: procedure price ₹40,600; total package ₹49,300–₹66,700 with bare-metal stents and ₹72,200–₹1,35,400 with drug-eluting stents, depending on the number of stents. Rates are revised over time and some states set their own.","source_id":"src-nha-hbp21"},{"text":"Treatment is portable: beneficiaries can use empanelled hospitals in other states.","source_id":"src-pib-pmjay-6yrs"}]'::jsonb, '₹5 lakh is a yearly ceiling shared by the family, not money paid to you. Treatment at non-empanelled hospitals, items outside the approved package, and care that was not pre-authorised may not be covered. Ask the hospital''s Ayushman desk what the package includes before admission.', 'Check beneficiary status and get an Ayushman card online or at an empanelled hospital''s Ayushman desk; the hospital then seeks pre-authorisation for treatment.', '[{"text":"Check whether the family is listed as a beneficiary on the official NHA beneficiary portal, or ask at an empanelled hospital''s Ayushman desk.","source_id":null},{"text":"Carry the Ayushman card and a valid photo ID to an empanelled hospital.","source_id":"src-iggmc-integrated"},{"text":"At admission the treating doctor raises a pre-authorisation under the relevant package code and identity is verified at the Ayushman Bharat counter; the scheme approves the package.","source_id":"src-aiimsbbsr-pmjay-doc"},{"text":"At discharge identity is verified again and the hospital closes the claim with the scheme. (Process as described by AIIMS Bhubaneswar; other hospitals may differ in detail.)","source_id":"src-aiimsbbsr-pmjay-doc"}]'::jsonb, 'https://beneficiary.nha.gov.in/', 'official_domain_unfetched', 'https://pmjay.gov.in/', 'https://hospitals.pmjay.gov.in/', '[{"text":"National PM-JAY helpline: 14555","source_id":"src-manipur-grievance"},{"text":"Online grievance portal: https://cgrms.nha.gov.in/","source_id":"src-manipur-grievance"}]'::jsonb, 'partially_verified', '2026-10-29', '2024-09-23', array['Whether a particular family is a beneficiary can only be confirmed against the official database.', 'Package rates are revised periodically (HBP versions) and some states set their own rates.', 'pmjay.gov.in and beneficiary.nha.gov.in are official NHA domains, but our automated check on 2026-10-29 could not read their pages.', 'States can customise the package list. For example, Punjab''s 2020–21 list reserved knee replacement (SB039) for government hospitals — check your state''s current rules.']::text[], false),
  ('pmjay-senior-70', 'AB PM-JAY coverage for senior citizens aged 70 years and above', 'PM-JAY 70+ (Vay Vandana)', 'National Health Authority, Ministry of Health and Family Welfare, Government of India', 'national', '{}'::text[], 'Everyone aged 70 or older is eligible for AB PM-JAY cover regardless of income, through a separate card for senior citizens.', 'All citizens aged 70 years and above, irrespective of socio-economic status.', 500000, 'per year — on a family basis for seniors not already covered; as an exclusive top-up for the senior if the family is already covered', 'cashless_package', 'hospital', '[{"text":"Free health cover of up to ₹5 lakh per year.","source_id":"src-nha-70plus"},{"text":"If the family is already covered under AB PM-JAY, the senior gets an additional top-up of up to ₹5 lakh per year for themselves, not shared with family members under 70.","source_id":"src-nha-70plus"},{"text":"Seniors in families not already covered get up to ₹5 lakh per year on a family basis.","source_id":"src-nha-70plus"},{"text":"Care is cashless at empanelled hospitals, with the scheme paying the hospital for approved packages.","source_id":"src-pib-pmjay-6yrs"}]'::jsonb, 'The amount is a yearly ceiling, not a payment to the patient. Items outside the approved package or care at non-empanelled hospitals may not be covered.', 'Enrol the senior for the separate AB PM-JAY senior-citizen card, then use it at an empanelled hospital.', '[{"text":"Enrol the senior citizen for the new, distinct AB PM-JAY card issued to people aged 70 and above.","source_id":"src-nha-70plus"},{"text":"Take the card and ID to an empanelled hospital''s Ayushman desk; the hospital seeks pre-authorisation for the treatment package.","source_id":"src-aiimsbbsr-pmjay-doc"}]'::jsonb, 'https://beneficiary.nha.gov.in/', 'official_domain_unfetched', 'https://pmjay.gov.in/', 'https://hospitals.pmjay.gov.in/', '[{"text":"National PM-JAY helpline: 14555","source_id":"src-manipur-grievance"}]'::jsonb, 'partially_verified', '2026-10-29', '2024-09-11', array['Media reports call the card ''Ayushman Vay Vandana''; the official release we verified describes it as ''a new distinct card''.', 'The enrolment documents were not listed in the sources we could verify.']::text[], false),
  ('mh-mjpjay-integrated', 'Integrated Ayushman Bharat – PM-JAY and Mahatma Jyotirao Phule Jan Arogya Yojana (MJPJAY)', 'MJPJAY + PM-JAY (Maharashtra)', 'Government of Maharashtra (State Health Assurance Society), with the National Health Authority', 'state', array['MH']::text[], 'Maharashtra''s combined scheme: cashless treatment for listed health benefit packages at network hospitals, open to nearly all families in the state.', 'Category A: yellow, AAY, Annapurna and orange ration-card holders and PM-JAY households. Category B: white ration-card holders (including government employees) and families without a ration card who hold a Maharashtra domicile certificate. Category C: listed institutional groups such as ashram-school students, children in orphanages, residents of old-age homes, journalists and registered construction workers from outside Maharashtra. Separate categories cover road-accident victims and certain Karnataka border villages.', 500000, 'per family per year, floater (categories A, B, C and E)', 'cashless_package', 'hospital', '[{"text":"Up to ₹5 lakh per family per year on a floater basis.","source_id":"src-iggmc-integrated"},{"text":"Runs in assurance mode: the State Health Assurance Society pays network hospitals directly. The package covers treatment from admission to discharge, including complications.","source_id":"src-iggmc-integrated"},{"text":"1,356 health benefit packages across 34 specialties, plus follow-up packages.","source_id":"src-iggmc-integrated"},{"text":"Packages include one-time transport, and transport of the body if the patient dies.","source_id":"src-iggmc-integrated"},{"text":"Reference rates in the 1,356-package master: Coronary Balloon Angioplasty (M7F1.1) ₹60,000; each additional PTCA stent (M7F1.2) ₹20,000. Rates are paid to the hospital and may be revised.","source_id":"src-mjpjay-1356"}]'::jsonb, 'The ₹5 lakh is a family ceiling, not a payment to you. Procedures outside the listed packages and non-network hospitals are not covered by the scheme.', 'Through the Arogyamitra (scheme help desk) at any network hospital.', '[{"text":"Go to a network hospital and contact the Arogyamitra.","source_id":"src-iggmc-integrated"},{"text":"Show the Ayushman card or a qualifying ration card — or, for Category B without a ration card, a domicile or Tahsildar certificate with a self-declaration — along with ID proof.","source_id":"src-iggmc-integrated"},{"text":"The hospital registers the patient on the scheme''s portal and treatment proceeds cashless. In an emergency, the hospital can be informed by phone or email.","source_id":"src-iggmc-integrated"}]'::jsonb, 'https://www.jeevandayee.gov.in/', 'official_domain_unfetched', 'https://www.jeevandayee.gov.in/', 'https://www.jeevandayee.gov.in/', '[{"text":"The scheme runs a dedicated call centre for information and grievances; the number was not listed in the sources we could verify.","source_id":"src-iggmc-integrated"}]'::jsonb, 'partially_verified', '2026-10-29', null, array['Most scheme facts come from a government medical college''s summary; the package master and hospital list are read from jeevandayee.gov.in.', 'An older page on jeevandayee.gov.in still describes the earlier ₹1.5 lakh scheme. That is historical and is not used here.', 'Angioplasty and leukaemia packages are confirmed in the package master; knee replacement is only reported by a hospital, because our reading of the master stopped before Orthopaedics.', 'The official empanelled-hospital list we used is undated and has no specialities. Check the current list or ask the Arogyamitra desk.']::text[], false),
  ('ran-umbrella', 'Umbrella Scheme of Rashtriya Arogya Nidhi (RAN)', 'Rashtriya Arogya Nidhi', 'Ministry of Health and Family Welfare, Government of India', 'national', '{}'::text[], 'One-time financial assistance for poor patients with major life-threatening diseases who are treated at government hospitals.', 'Patients from families living below the threshold poverty line with a major life-threatening disease (such as heart, kidney, liver or cancer conditions), treated at a government hospital or institute.', 1500000, 'one-time assistance (up to ₹20 lakh under the rare-disease component)', 'one_time_grant_to_hospital', 'hospital', '[{"text":"One-time financial assistance of up to ₹15 lakh; up to ₹20 lakh under the rare-disease component.","source_id":"src-pib-ran-2022"},{"text":"Assistance is released to the treating government hospital, not paid to the patient.","source_id":"src-pib-ran-2022"},{"text":"At AIIMS Bhubaneswar, a sanction order with the amount and validity period goes to the hospital, with a copy to the applicant.","source_id":"src-aiimsbbsr-ran"}]'::jsonb, 'This is a one-time grant up to the sanctioned amount for treatment at the government hospital. Costs beyond the sanction, or treatment elsewhere, are not covered.', 'Through the treating government hospital (Medical Superintendent''s office or the RAN nodal officer).', '[{"text":"Get a treatment cost estimate from the treating government hospital.","source_id":"src-aiimsbbsr-ran"},{"text":"Submit the application form with the estimate and documents; it is countersigned by the Medical Superintendent.","source_id":"src-aiimsbbsr-ran"},{"text":"The hospital''s committee approves it, or the nodal officer forwards it to the Ministry, depending on the route. The sanction is issued to the hospital.","source_id":"src-aiimsbbsr-ran"}]'::jsonb, null, 'not_verified', 'https://mohfw.gov.in/major-programmes/poor-patients-financial-assistance/rashtriya-arogya-nidhi', null, '[]'::jsonb, 'partially_verified', '2026-10-29', '2022-07-22', array['The 2019 RAN guidelines on mohfw.gov.in could not be read by our checker; limits come from a 2022 Lok Sabha reply and AIIMS Bhubaneswar''s scheme page.', 'An older MoHFW page mentions ₹2 lakh per case; this appears to predate the umbrella scheme and is not used.', 'There is no patient-facing online application link we could verify.']::text[], false),
  ('hmcpf', 'Health Minister''s Cancer Patient Fund (HMCPF), under the Umbrella Scheme of RAN', 'HMCPF', 'Ministry of Health and Family Welfare, Government of India', 'national', '{}'::text[], 'One-time financial assistance for cancer patients from families below the poverty line, for treatment at government cancer institutions.', 'Cancer patients living below the State/UT-wise poverty line, treated at a Regional Cancer Centre, Tertiary Care Cancer Centre, State Cancer Institute or another government hospital with cancer treatment facilities.', 1500000, 'one-time assistance', 'one_time_grant_to_hospital', 'hospital', '[{"text":"One-time financial assistance of up to ₹15 lakh.","source_id":"src-ls-au5561"},{"text":"For treatment at RCCs, TCCCs, State Cancer Institutes and other government hospitals or institutes with cancer treatment facilities.","source_id":"src-ls-au5561"},{"text":"Under the RAN umbrella, assistance is released to the treating hospital.","source_id":"src-pib-ran-2022"}]'::jsonb, 'A one-time grant up to the sanctioned amount, paid to the treating government institution. It is not a cash payment to the patient.', 'Through the treating government cancer institution.', '[{"text":"Ask the medical social worker or scheme desk at the treating government cancer hospital about HMCPF assistance and the documents they need.","source_id":null}]'::jsonb, null, 'not_verified', 'https://eparlib.sansad.in/bitstream/123456789/3010946/1/AU5561_tNqey7.pdf', null, '[]'::jsonb, 'partially_verified', '2026-10-29', '2025-04-04', array['The application process and document list for HMCPF were not available in the sources we could verify.', 'We have not verified which specific hospitals currently process HMCPF applications.']::text[], false),
  ('hmdg', 'Health Minister''s Discretionary Grant (HMDG)', 'HMDG', 'Ministry of Health and Family Welfare, Government of India', 'national', '{}'::text[], 'Financial assistance of up to ₹1.25 lakh for poor, indigent patients where free treatment is not available.', 'Poor, indigent patients with an annual family income of ₹1.25 lakh or less.', 125000, 'maximum assistance', 'other', 'unknown', '[{"text":"Assistance up to a maximum of ₹1.25 lakh.","source_id":"src-pib-ran-2022"},{"text":"How and to whom HMDG is paid was not stated in the sources we could verify.","source_id":null}]'::jsonb, '₹1.25 lakh is a maximum, not a guaranteed amount.', 'Not verified. Ask the treating government hospital.', '[{"text":"The application route for HMDG was not described in the sources we could verify. Ask the treating government hospital''s social worker or scheme desk.","source_id":null}]'::jsonb, null, 'not_verified', 'https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=1843846&reg=48&lang=2', null, '[]'::jsonb, 'requires_verification', '2026-10-29', '2022-07-22', array['Which conditions qualify, the payment route and the application process are not verified.', 'The income limit is from a 2022 Lok Sabha reply and may have been revised.']::text[], false),
  ('pmnrf', 'Prime Minister''s National Relief Fund (PMNRF) – medical assistance', 'PMNRF', 'Prime Minister''s Office, Government of India', 'national', '{}'::text[], 'Partial financial help toward the cost of major treatments such as heart surgery, kidney transplantation and cancer treatment.', 'Needy people requiring major medical treatment; the fund decides each case.', null, null, 'partial_assistance', 'unknown', '[{"text":"The fund partially defrays treatment expenses. No amount or ceiling is published in the sources we verified.","source_id":"src-pmnrf"},{"text":"Central and state government hospitals are on the fund''s panel, and the site links to a list of empanelled private hospitals.","source_id":"src-pmnrf"}]'::jsonb, 'Assistance is partial. Expect to cover the remaining cost from other sources.', 'Application to the Prime Minister''s Office; see the official PMNRF website.', '[{"text":"The application process was not described on the pages we could verify. Check the official PMNRF website or ask the hospital''s medical social worker.","source_id":null}]'::jsonb, 'https://pmnrf.gov.in/', 'official_verified', 'https://pmnrf.gov.in/', null, '[{"text":"Under Secretary (Funds), PMNRF, Prime Minister''s Office, South Block, New Delhi-110011. Phone 011-23013683.","source_id":"src-gcri-pmnrf"}]'::jsonb, 'partially_verified', '2026-10-29', null, array['Eligibility rules, amounts and the document list are not published on the pages we verified.', 'The contact details come from a hospital''s copy of PMNRF information, not from the PMNRF site.']::text[], false),
  ('kl-kasp', 'Karunya Arogya Suraksha Padhathi (KASP)', 'KASP', 'State Health Agency Kerala, Government of Kerala', 'state', array['KL']::text[], 'Kerala''s health assurance scheme, run alongside AB PM-JAY: cashless secondary and tertiary hospitalisation for covered families at empanelled hospitals.', 'About 42 lakh families (around 64 lakh people) in the bottom 40% of Kerala''s population, identified using SECC 2011 deprivation and occupational criteria. Earlier schemes (RSBY, CHIS, SCHIS) were merged into KASP.', 500000, 'per family per year, shared by all members (floater)', 'cashless_package', 'hospital', '[{"text":"Health cover of up to ₹5 lakh per family per year for secondary and tertiary care hospitalisation, on a family-floater basis.","source_id":"src-sha-kerala-kasp"},{"text":"Cashless at the point of service in empanelled hospitals.","source_id":"src-sha-kerala-kasp"},{"text":"No cap on family size or on the age of members.","source_id":"src-sha-kerala-kasp"},{"text":"Covers approximately 1,573 procedures.","source_id":"src-sha-kerala-kasp"}]'::jsonb, '₹5 lakh is a yearly ceiling shared by the family, not money paid to you. Care outside the approved package or at a non-empanelled hospital may not be covered. Ask the hospital''s scheme desk what is included before admission.', 'Through a KASP-empanelled hospital. The State Health Agency can confirm whether a family is covered.', '[{"text":"Before admission, ask a KASP-empanelled hospital''s scheme desk whether the family is covered.","source_id":null},{"text":"For questions about coverage, contact the State Health Agency Kerala.","source_id":"src-sha-kerala-kasp"}]'::jsonb, null, 'not_verified', 'https://sha.kerala.gov.in/?page_id=110&lang=en', null, '[{"text":"State Health Agency Kerala: 0471 4063121","source_id":"src-sha-kerala-kasp"},{"text":"Email: statehealthagencykerala@gmail.com","source_id":"src-sha-kerala-kasp"}]'::jsonb, 'partially_verified', '2026-10-29', null, array['Whether a family is covered can only be confirmed by the State Health Agency or an empanelled hospital.', 'The official page doesn''t list individual packages, so we haven''t verified that knee replacement, angioplasty or leukaemia treatment are among the ~1,573 procedures.', 'We could not find an official online application or hospital-search page.', 'Kerala has reportedly approved, in principle, a separate ''Health Protection for All'' programme for residents outside existing schemes (news report, Aug 2026). No start date was given.']::text[], false),
  ('kl-kbf', 'Karunya Benevolent Fund (KBF)', 'KBF', 'State Health Agency Kerala, Government of Kerala', 'state', array['KL']::text[], 'Kerala''s treatment fund for serious illness — cancer, haemophilia, kidney and heart disease, and palliative care — now run with KASP: cashless treatment at KASP-empanelled hospitals for families with annual income below ₹3 lakh.', 'Patients with cancer, haemophilia, kidney or heart disease, or needing palliative care, from families with an annual income of less than ₹3 lakh.', null, 'No current limit is stated on the official page', 'cashless_package', 'hospital', '[{"text":"Covers secondary and tertiary care under KASP packages, including hospitalisation or day-care charges and medicines for 15 days after discharge.","source_id":"src-sha-kerala-kbf"},{"text":"Treatment is cashless at KASP-empanelled hospitals.","source_id":"src-sha-kerala-kbf"},{"text":"For context only: under the earlier scheme run by the State Lotteries Department, limits were ₹2 lakh for tertiary care and ₹3 lakh for kidney ailments. The official page does not say these limits apply to the revamped fund.","source_id":"src-sha-kerala-kbf"},{"text":"A news report (Aug 2026) describes KBF as offering up to ₹2 lakh, plus up to ₹1 lakh for kidney disease. This is not confirmed on the official page.","source_id":"src-dhn-kerala-uhc"}]'::jsonb, 'The official page doesn''t state a current limit, so we can''t say how much will be covered. Ask the hospital''s scheme desk before admission.', 'Apply directly at a KASP-empanelled hospital; it is processed through the scheme''s IT system.', '[{"text":"Go to a KASP-empanelled hospital and ask for Karunya Benevolent Fund assistance.","source_id":"src-sha-kerala-kbf"},{"text":"Bring the family''s ration card with proof of income.","source_id":"src-sha-kerala-kbf"},{"text":"The hospital processes the request through the scheme''s IT-integrated system. Treatment is cashless once approved.","source_id":"src-sha-kerala-kbf"}]'::jsonb, null, 'not_verified', 'https://sha.kerala.gov.in/?page_id=2961&lang=en', null, '[{"text":"State Health Agency Kerala: 0471 4063121","source_id":"src-sha-kerala-kbf"}]'::jsonb, 'partially_verified', '2026-10-29', null, array['The official page does not state a current benefit limit for the revamped fund.', 'A news report says KBF is for families not covered by KASP; the official page doesn''t say this. The hospital or State Health Agency will confirm.', 'Whether a particular treatment is covered depends on the KASP package list, which we haven''t verified procedure by procedure.']::text[], false)
