insert into public.scheme_treatments (scheme_id, medical_need_id, coverage_level, coverage_note, source_id) values
  ('pmjay-family', 'angioplasty', 'procedure_verified', 'Package MC011 ''PTCA, inclusive of diagnostic angiogram'' (Cardiology) is in the NHA HBP 2.1 list.', 'src-nha-hbp21'),
  ('pmjay-family', 'leukemia', 'category_verified', '549 of the scheme''s procedures are cancer-related, and NHA''s HBP 2.0 list includes leukaemia chemotherapy packages (e.g. MO065B for paediatric APL induction). The exact package depends on the leukaemia type and protocol.', 'src-ls-au2641'),
  ('pmjay-family', 'knee-replacement', 'procedure_verified', 'A Ministry of Health reply in Lok Sabha (29 Nov 2024) names Total Knee Replacement among AB PM-JAY services, under the Orthopaedics specialty. The HBP 2.0 package code is SB039 (primary and revision). States may customise packages — some have reserved knee replacement for government hospitals — so confirm at the hospital''s Ayushman desk.', 'src-ls-au720'),
  ('pmjay-senior-70', 'angioplasty', 'procedure_verified', 'Uses the AB PM-JAY package list; PTCA (MC011) is in HBP 2.1.', 'src-nha-hbp21'),
  ('pmjay-senior-70', 'leukemia', 'category_verified', 'Uses the AB PM-JAY package list, which includes cancer and leukaemia packages.', 'src-ls-au2641'),
  ('pmjay-senior-70', 'knee-replacement', 'procedure_verified', 'A Ministry of Health reply in Lok Sabha (29 Nov 2024) on cover for senior citizens names Total Knee Replacement among the services available to them under AB PM-JAY. States may customise packages, so confirm at the hospital''s Ayushman desk.', 'src-ls-au720'),
  ('mh-mjpjay-integrated', 'knee-replacement', 'secondary_source', 'AIIMS Nagpur reports performing total knee replacements under MJPJAY and PM-JAY. The official package master we could read stops before its Orthopaedics section, so the package itself isn''t confirmed.', 'src-aiimsngp-joint'),
  ('mh-mjpjay-integrated', 'angioplasty', 'procedure_verified', 'The scheme''s 1,356-package master lists Coronary Balloon Angioplasty (M7F1.1) and PTCA Additional Stent (M7F1.2) under Cardiology.', 'src-mjpjay-1356'),
  ('mh-mjpjay-integrated', 'leukemia', 'procedure_verified', 'The scheme''s 1,356-package master lists Haemato-Oncology packages for acute myeloid leukaemia, acute lymphoblastic leukaemia and APML (e.g. M19U3.1 AML induction, M19U2.2 ALL induction). The package used depends on the leukaemia type and protocol.', 'src-mjpjay-1356'),
  ('ran-umbrella', 'angioplasty', 'unverified', 'Heart disease is named among the life-threatening conditions covered; whether a particular angioplasty qualifies is decided case by case.', 'src-aiimsbbsr-ran'),
  ('hmcpf', 'leukemia', 'category_verified', 'Leukaemia is a cancer, and the fund covers cancer treatment.', 'src-ls-au5561'),
  ('hmdg', 'angioplasty', 'unverified', 'Which conditions HMDG covers was not stated in the sources we verified.', 'src-pib-ran-2022'),
  ('hmdg', 'leukemia', 'unverified', 'Cancer is named among conditions in the related RAN schemes; HMDG''s own condition list was not verified.', 'src-ls-au2641'),
  ('pmnrf', 'leukemia', 'category_verified', 'Cancer treatment is named among the treatments the fund partially supports.', 'src-pmnrf'),
  ('pmnrf', 'angioplasty', 'unverified', 'Heart surgery is named; whether angioplasty qualifies is decided by the fund.', 'src-pmnrf'),
  ('kl-kasp', 'knee-replacement', 'unverified', 'KASP covers about 1,573 procedures; we did not verify that knee replacement is one of them. Kerala''s 2020 service contract names the national HBP 2.0 list as KASP''s package list, but we couldn''t check the current Kerala list.', 'src-sha-kerala-contract'),
  ('kl-kasp', 'angioplasty', 'unverified', 'KASP covers about 1,573 procedures; we did not verify that angioplasty is one of them. Kerala''s 2020 service contract names the national HBP 2.0 list as KASP''s package list, but we couldn''t check the current Kerala list.', 'src-sha-kerala-contract'),
  ('kl-kasp', 'leukemia', 'unverified', 'KASP covers about 1,573 procedures; we did not verify that leukaemia treatment is one of them. Kerala''s 2020 service contract names the national HBP 2.0 list as KASP''s package list, but we couldn''t check the current Kerala list.', 'src-sha-kerala-contract'),
  ('kl-kbf', 'leukemia', 'category_verified', 'Cancer is named among the conditions KBF supports. The exact package depends on the type of leukaemia and the treatment.', 'src-sha-kerala-kbf'),
  ('kl-kbf', 'angioplasty', 'unverified', 'Heart disease is named among the conditions KBF supports; whether a particular angioplasty is covered depends on the KASP package list.', 'src-sha-kerala-kbf');
insert into public.scheme_eligibility_rules (id, scheme_id, criterion, definition, mandatory, any_of_group, official_text, source_id, sort_order) values
  ('pmjay-family-beneficiary', 'pmjay-family', 'beneficiary_status', '{"type":"pmjay_beneficiary","accepted":["has_card","listed"]}'::jsonb, true, null, 'The family must be an eligible PM-JAY beneficiary household (identified from SECC 2011 data or an approved expansion).', 'src-pib-pmjay-6yrs', 1),
  ('pmjay-family-income', 'pmjay-family', 'income', '{"type":"informational"}'::jsonb, false, null, 'Eligibility comes from SECC 2011 deprivation and occupation criteria, not from a single income limit.', 'src-pib-pmjay-6yrs', 2),
  ('pmjay-family-residence', 'pmjay-family', 'residence', '{"type":"no_restriction","note":"National scheme: beneficiaries can be treated at empanelled hospitals in any state."}'::jsonb, true, null, 'Portable across India.', 'src-pib-pmjay-6yrs', 3),
  ('pmjay70-age', 'pmjay-senior-70', 'age', '{"type":"age_range","min":70}'::jsonb, true, null, 'The person must be 70 years of age or older.', 'src-nha-70plus', 1),
  ('pmjay70-income', 'pmjay-senior-70', 'income', '{"type":"no_restriction","note":"The official release says seniors aged 70+ are eligible irrespective of income or socio-economic status."}'::jsonb, true, null, 'Eligible irrespective of income.', 'src-nha-70plus', 2),
  ('pmjay70-insurance', 'pmjay-senior-70', 'insurance', '{"type":"insurance_not_excluded"}'::jsonb, true, null, 'Seniors with private health insurance or under the Employees'' State Insurance scheme are eligible.', 'src-nha-70plus', 3),
  ('pmjay70-cghs', 'pmjay-senior-70', 'insurance', '{"type":"informational"}'::jsonb, false, null, 'Seniors already covered by CGHS, ECHS or CAPF schemes can keep their existing scheme or choose AB PM-JAY.', 'src-nha-70plus', 4),
  ('mh-residence', 'mh-mjpjay-integrated', 'residence', '{"type":"residence_state","states":["MH"]}'::jsonb, true, null, 'For families of Maharashtra (ration-card or domicile based categories).', 'src-iggmc-integrated', 1),
  ('mh-document', 'mh-mjpjay-integrated', 'beneficiary_status', '{"type":"state_beneficiary_document","state":"MH","description":"a Maharashtra ration card (yellow, orange, white, AAY or Annapurna) or a Maharashtra domicile certificate"}'::jsonb, true, 'mh-entry', 'Category A/B: a qualifying Maharashtra ration card, or a domicile certificate for families without one.', 'src-iggmc-integrated', 2),
  ('mh-category-c', 'mh-mjpjay-integrated', 'beneficiary_status', '{"type":"requires_official_check"}'::jsonb, true, 'mh-entry', 'Category C: belongs to a listed institutional group (e.g. ashram-school student, orphanage child, old-age-home resident, journalist, registered construction worker from outside the state).', 'src-iggmc-integrated', 3),
  ('ran-poverty', 'ran-umbrella', 'income', '{"type":"requires_official_check"}'::jsonb, true, null, 'The family must be living below the threshold poverty line. AIIMS Bhubaneswar also lists PM-JAY (SECC) beneficiaries for treatments PM-JAY does not cover, and NFSA AAY/PHH ration-card holders.', 'src-aiimsbbsr-ran', 1),
  ('ran-facility', 'ran-umbrella', 'facility', '{"type":"requires_official_check"}'::jsonb, true, null, 'Treatment must be at a government hospital or institute.', 'src-pib-ran-2022', 2),
  ('ran-pmjay-overlap', 'ran-umbrella', 'other', '{"type":"informational"}'::jsonb, false, null, 'Treatments covered under PM-JAY are outside this scheme for PM-JAY beneficiaries.', 'src-aiimsbbsr-ran', 3),
  ('hmcpf-poverty', 'hmcpf', 'income', '{"type":"requires_official_check"}'::jsonb, true, null, 'The patient must be living below the State/UT-wise poverty line.', 'src-ls-au5561', 1),
  ('hmcpf-facility', 'hmcpf', 'facility', '{"type":"requires_official_check"}'::jsonb, true, null, 'Treatment at an RCC, TCCC, State Cancer Institute or another government hospital with cancer treatment facilities.', 'src-ls-au5561', 2),
  ('hmdg-income', 'hmdg', 'income', '{"type":"income_max","maxAnnualIncomeInr":125000}'::jsonb, true, null, 'Annual family income of ₹1.25 lakh or less.', 'src-pib-ran-2022', 1),
  ('hmdg-facility', 'hmdg', 'facility', '{"type":"requires_official_check"}'::jsonb, true, null, 'For poor, indigent patients where free medical facilities are not available.', 'src-pib-ran-2022', 2),
  ('pmnrf-need', 'pmnrf', 'other', '{"type":"requires_official_check"}'::jsonb, true, null, 'Assistance is for needy people; the fund decides eligibility and the amount for each case.', 'src-pmnrf', 1),
  ('kl-kasp-residence', 'kl-kasp', 'residence', '{"type":"residence_state","states":["KL"]}'::jsonb, true, null, 'For families in Kerala (the bottom 40% of the state''s population).', 'src-sha-kerala-kasp', 1),
  ('kl-kasp-household', 'kl-kasp', 'beneficiary_status', '{"type":"requires_official_check"}'::jsonb, true, null, 'The family must be one of the households covered by KASP, identified using SECC 2011 deprivation and occupational criteria.', 'src-sha-kerala-kasp', 2),
  ('kl-kasp-age', 'kl-kasp', 'age', '{"type":"no_restriction","note":"No cap on family size or on members'' age."}'::jsonb, true, null, 'There is no cap on family size or age of members.', 'src-sha-kerala-kasp', 3),
  ('kl-kbf-residence', 'kl-kbf', 'residence', '{"type":"residence_state","states":["KL"]}'::jsonb, true, null, 'A Kerala State Health Agency fund; applicants show a ration card with proof of income.', 'src-sha-kerala-kbf', 1),
  ('kl-kbf-income', 'kl-kbf', 'income', '{"type":"income_max","maxAnnualIncomeInr":300000,"exclusive":true}'::jsonb, true, null, 'Annual family income of less than ₹3 lakh.', 'src-sha-kerala-kbf', 2),
  ('kl-kbf-document', 'kl-kbf', 'beneficiary_status', '{"type":"state_beneficiary_document","state":"KL","description":"a Kerala ration card, with proof of income"}'::jsonb, true, null, 'A ration card with income proof is required.', 'src-sha-kerala-kbf', 3),
  ('kl-kbf-not-kasp', 'kl-kbf', 'other', '{"type":"informational"}'::jsonb, false, null, 'Reported (news, Aug 2026) to be for families not covered under KASP. Not stated on the official page.', 'src-dhn-kerala-uhc', 4);
insert into public.scheme_documents (scheme_id, document, note, source_id, is_provisional, sort_order) values
