  ('pmjay-family', 'Investigation reports and the doctor''s pre-authorisation form (prepared by the hospital)', 'As described by AIIMS Bhubaneswar.', 'src-aiimsbbsr-pmjay-doc', false, 4),
  ('pmjay-senior-70', 'Proof of age and identity for enrolment', 'Generic preparation item. The exact enrolment documents were not listed in our verified sources.', null, true, 1),
