  ('mh-mjpjay-integrated', 'Ayushman card, or a qualifying ration card (yellow, orange, AAY, Annapurna or white)', null, 'src-iggmc-integrated', false, 1),
  ('mh-mjpjay-integrated', 'Valid photo ID proof', null, 'src-iggmc-integrated', false, 2),
  ('mh-mjpjay-integrated', 'Category B without a ration card: Maharashtra domicile certificate or Tahsildar certificate, with a self-declaration', null, 'src-iggmc-integrated', false, 3),
  ('mh-mjpjay-integrated', 'Government employees: white ration card and a self-declaration', null, 'src-iggmc-integrated', false, 4),
  ('mh-mjpjay-integrated', 'Category C: valid ID issued by the institution or organisation', null, 'src-iggmc-integrated', false, 5),
  ('ran-umbrella', 'Income certificate for the family, covering all sources', 'As listed by AIIMS Bhubaneswar for manual applications.', 'src-aiimsbbsr-ran', false, 1),
  ('ran-umbrella', 'Ration card (with a Hindi or English translation if it is in a regional language)', null, 'src-aiimsbbsr-ran', false, 2),
  ('ran-umbrella', 'Aadhaar card copy', null, 'src-aiimsbbsr-ran', false, 3),
  ('ran-umbrella', 'Filled application form with the hospital''s treatment estimate', null, 'src-aiimsbbsr-ran', false, 4),
  ('hmcpf', 'Proof of income or poverty-line status, ID proof and the hospital''s treatment estimate', 'Generic preparation checklist. The official HMCPF document list was not verified.', null, true, 1),
  ('hmdg', 'Income proof showing annual family income, ID proof and the hospital''s treatment estimate', 'Generic preparation checklist. The official HMDG document list was not verified.', null, true, 1),
  ('pmnrf', 'Hospital treatment estimate, income proof and ID proof', 'Generic preparation checklist. PMNRF''s official document list was not verified.', null, true, 1),
  ('kl-kasp', 'Photo ID and whatever proof of coverage the hospital or State Health Agency asks for', 'Generic preparation checklist. KASP''s official document list was not verified.', null, true, 1),
  ('kl-kbf', 'Ration card with proof of income', null, 'src-sha-kerala-kbf', false, 1),
  ('kl-kbf', 'Treating doctor''s diagnosis and the hospital''s treatment plan', 'Generic preparation checklist, not from the official page.', null, true, 2);
