  ('aiims-bbsr', 'All India Institute of Medical Sciences, Bhubaneswar', 'Sijua, Patrapada', 'Bhubaneswar', 'Khordha', 'OD', '751019', 20.2313, 85.7741, 'Approximate coordinates from public map data, not from an official source.', '(0674) 2476789 (helpdesk)', 'https://aiimsbhubaneswar.nic.in/', 'hospital_official_source', '2026-10-29', 'src-aiimsbbsr-pmjay'),
